$steps += @{ Name = 'T21 Button flow by hand r5: make the flow'; Title = 'Make the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make a new flow in the solution with the trigger "For a selected item". About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select the solution "90-161.Z probe button".', '2. On the left, select "Objects".', '3. Select "New".', '4. Select "Automation".', '5. Select "Cloud flow".', '6. Select "Instant".', '7. In the box "Flow name", type: 90161Z T21 Probe Button hand r5', '8. In the search box of the trigger list, type: For a selected item', '9. Select the trigger "For a selected item" (SharePoint).', '10. Select "Create".', 'If no trigger "For a selected item" is listed: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-trigger.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: set the trigger.'; Makes = @(); After = @('T21 Button flow by hand r5: make a solution'); Optional = $false; Help = '' }
