$steps += @{ Name = 'T21 Button flow by hand r5: the action'; Title = 'Add the action and save the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You add one action that writes a row, then save the flow. About 5 minutes.'; Kind = 'guide'; Guide = @('1. Under the trigger, select "New step".', '2. In the search box, type: Create item', '3. Select the SharePoint action "Create item".', '4. In the box "Site Address", select the site whose address matches the one you typed in RADE.', '5. In the box "List Name", select "90161Z Probe".', '6. In the box "Title", type: BTN-HAND', '7. Select "Save".', '8. Look at the top for the word "Saved".', 'If "Create item" is not listed: select "It failed".', 'If "Save" shows an error: select "It failed".', 'If that site is not listed: select "Enter custom value".', 'If a box opens for the value: type the same address as in the RADE box "Site address".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-action.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: saved the button flow.'; Makes = @(); After = @('T21 Button flow by hand r5: site and list'); Optional = $false; Help = '' }
$steps += @{ Name = 'T21 Button flow by hand r5: export the solution'; Title = 'Export the button flow solution'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You export the solution "90-161.Z probe button" and save the file in your Downloads folder. The next step reads it there. About 5 minutes.'; Kind = 'guide'; Guide = @('1. On the left, select "Solutions" (it can be under "More").', '2. Select the solution "90-161.Z probe button".', '3. In the top bar, select "Export solution".', '4. If the page offers "Publish": select it.', '5. Select "Next".', '6. Select "Unmanaged".', '7. Select "Export".', '8. When the page says the export is ready, select "Download".', '9. If the browser asks what to do with the file: select "Save".', '10. In File Explorer (press Windows+E), select "Downloads" on the left.', 'Look for the newest .zip file in that folder: it is the export.', 'If no .zip file is in Downloads: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-exported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: exported the button solution.'; Makes = @(); After = @('T21 Button flow by hand r5: the action'); Optional = $false; Help = '' }
$steps += @{ Name = 'T21 Read the export r5'; Title = 'Read the exported button flow'; Dir = 'T21'; File = '90161Z-T21-probe-r5.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part Export'; Note = 'Reads the newest export file in Downloads. If it holds 1 flow, reads that flow whatever its name. Writes only the trigger''s type, kind, operation and parameter names. No sign-in.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Button flow by hand r5: export the solution'); Optional = $false; Help = 'Send the results as they are. No value, site or address is written.' }
