  $t += $dot + 'about ' + [math]::Max(1, [int][math]::Round($est / 60)) + ' min' + $dot + @($A.Checks).Count + ' checks'
  $i = Get-InstalledText $A; if ($i) { $i = $i.Substring(0, 1).ToUpperInvariant() + $i.Substring(1) }
  return @{ Steps = $t; Installed = $i }
}
